ASCII = ''' !"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~'''
VI = 'ÀÁÂÃÇÈÉÊÌÍÑÒÓÔÕÙÚÝàáâãçèéêìíñòóôõùúýĂăĐđĨĩŨũƠơƯưẠạẢảẤấẦầẨẩẪẫẬậẮắẰằẲẳẴẵẶặẸẹẺẻẼẽẾếỀềỂễỆệỈỉỊịỌọỎỏỐốỒồỔỗỘỚớỜờỞởỠỡỢợỤụỦủỨứỪừỬửỮữỰựỲỳỴỵỶỷỸỹ'
# Recovered exact sorted target 138 Vietnamese chars from the supplied font version.
VI = 'ÀÁÂÃÇÈÉÊÌÍÑÒÓÔÕÙÚÝàáâãçèéêìíñòóôõùúýĂăĐđĨĩŨũƠơƯưẠạẢảẤấẦầẨẩẪẫẬậẮắẰằẲẳẴẵẶặẸẹẺẻẼẽẾếỀềỂễỆệỈỉỊịỌọỎỏỐốỒồỔỖỗỘộỚớỜờỞởỠỡỢợỤụỦủỨứỪừỬửỮữỰựỲỳỴỵỶỷỸỹ'
# Do not rely on the manually typed list above if not complete: the builder obtains the list from the previous glyph catalogue.

B64_ASCII={
'6r':'''''',
'6b':'''AAAAAAAAAAAAAAAAAAAA ''',
'8r':'''AAAAAAAAAAAAAAAAAAAA ''',
'8b':'''''',
}
B64_ASCII={k:''.join(v.split()) for k,v in B64_ASCII.items()}

def source_ascii(key):
    blob=base64.b64decode(B64_ASCII[key])
    if key=='6r' and len(blob)==1229:
        # recovered six missing zero bytes inside the underscore glyph in transfer
        blob=blob[:824]+bytes(6)+blob[824:]
    assert len(blob)==95*13,(key,len(blob))
    return {chr(i+32):list(blob[i*13:(i+1)*13]) for i in range(95)}

# X11 Regular precomposed Latin letters (138 Unicode glyphs, matches previous
# 345-glyph Oxalis catalogue). Source BDF itself provides all Vietnamese forms.
B64_VI_REG={
'6r': '''''',
'8r': ''''''
}
B64_VI_REG={k:''.join(v.split()) for k,v in B64_VI_REG.items()}
def source_vietnamese(key, chars):
    blob=base64.b64decode(B64_VI_REG[key]);assert len(blob)==len(chars)*13,(key,len(blob),len(chars))
    return {ch:list(blob[i*13:(i+1)*13]) for i,ch in enumerate(chars)}
